// Кандидаты на повтор: упал Vision (asset.process) и partial-черновик (metadata.build).
const vision = $('Vision failed').first().json;
const drafts = $input.first().json;
for (const [name, e] of [['vision', vision], ['drafts', drafts]]) {
  if (!e.ok) throw new Error(`asset.list ${name}: ${JSON.stringify(e.error)}`);
}
const items = [
  ...vision.data.items.map(a => ({ asset_id: a.id, filename: a.filename, stage: 'AI', operation: 'asset.process' })),
  ...drafts.data.items
    .filter(a => a.pipeline.metadata_completeness === 'partial')
    .map(a => ({ asset_id: a.id, filename: a.filename, stage: 'METADATA_AI', operation: 'metadata.build' })),
];
return items.map(json => ({ json }));

const MAX_FAILED = 3;
const candidates = $('Candidates').all();
return $input.all().map((item, index) => {
  const candidate = candidates[index].json;
  const e = item.json;
  const events = e.ok ? e.data : [];
  const failedEvents = events.filter(ev => ev.stage === candidate.stage && ev.status === 'FAILED');
  const last = failedEvents[failedEvents.length - 1];
  const message = last && typeof last.message === 'object' ? last.message : {};
  const exhaustedKey = `${candidate.stage}:${failedEvents.length}`;
  const alreadyNotified = events.some(ev => ev.stage === 'NOTIFY' && ev.status === 'SENT'
    && ev.message && ev.message.kind === 'retry_exhausted' && ev.message.key === exhaustedKey);
  let action = 'retry';
  if (!e.ok) action = 'history_error';
  else if (failedEvents.length >= MAX_FAILED) action = alreadyNotified ? 'exhausted_notified' : 'exhausted';
  return { json: {
    ...candidate,
    failed: failedEvents.length,
    exhausted_key: exhaustedKey,
    last_error: last ? `${message.error_type || ''}: ${message.error || ''}` : null,
    action,
  } };
});

const MAX_PER_RUN = 5;
return $input.all()
  .filter(item => item.json.action === 'retry')
  .slice(0, MAX_PER_RUN)
  .map(item => ({ json: item.json }));

// Итог повторов. Успех определяет ответ Stocker (ok), а не факт HTTP-ответа.
const planned = $('Retry items').all();
const results = $input.all().map((item, index) => {
  const p = planned[index].json;
  const e = item.json;
  const recovered = e.ok === true;
  return { asset_id: p.asset_id, filename: p.filename, operation: p.operation, attempt: p.failed + 1,
           recovered, outcome: e.outcome || null, error: e.error ? (e.error.code || e.error.message || String(e.error)) : null };
});
const failed = results.filter(r => !r.recovered);
const lines = [
  `Повторов: ${results.length}, успешно: ${results.length - failed.length}, снова ошибка: ${failed.length}`,
  ...failed.map(r => `#${r.asset_id} ${r.filename}: ${r.operation}, попытка ${r.attempt}, ${r.outcome || r.error}`),
];
return [{ json: {
  severity: failed.length ? 'warning' : 'info',
  title: 'Stocker: повторная обработка',
  text: lines.join('\n'),
  data: { results },
  kind: 'retry_report',
  items: results.map(r => ({ asset_id: r.asset_id, key: `${r.operation}:${r.attempt}` })),
} }];

// Уведомление о повторных ошибках — только если в Stocker ещё нет NOTIFY/SENT с этим ключом.
const today = new Date().toISOString().slice(0, 10);
const fresh = $input.all()
  .map(item => item.json)
  .filter(p => p.action === 'exhausted' || p.action === 'history_error');
if (!fresh.length) return [];
const lines = fresh.map(p => p.action === 'history_error'
  ? `#${p.asset_id} ${p.filename}: не удалось получить историю`
  : `#${p.asset_id} ${p.filename}: ${p.operation} — ${p.failed} неудач, автоповторы остановлены. Последняя ошибка: ${p.last_error}`);
return [{ json: {
  severity: 'warning',
  title: 'Stocker: повторы исчерпаны',
  text: lines.join('\n'),
  data: { assets: fresh },
  kind: 'retry_exhausted',
  items: fresh.map(p => ({ asset_id: p.asset_id, key: p.action === 'history_error' ? `history_error:${today}` : p.exhausted_key })),
} }];
